package javatasks;

public class Basics3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int m = 20;
		int n = 34;
		
		System.out.println("Before swapping numbers are : m = " + m + ", n = " +n);
		
		int k = m;
		m = n;
		n= k;
		
		System.out.println("After swapping numbers are : m = " + m + ", n = "+ n);
		

	}

}
